{
  "lessons": [
    {
      "canDo": "Calculate a price or salary's percent change",
      "description": "Learn to compare a price or salary change with its starting amount, including why a 50% drop takes a 100% rise to recover.",
      "estimatedMinutes": 4,
      "screens": [
        {
          "activityTemplate": null,
          "kind": "hook",
          "visual": null,
          "visualKind": "none",
          "brief": "At a grocery store, a bottle of olive oil drops from $10 to $8, then returns to $10. Both moves are $2; are their percentage changes equal?",
          "skills": []
        },
        {
          "activityTemplate": null,
          "kind": "explanation",
          "visual": null,
          "visualKind": "none",
          "brief": "Judge a change against the amount it started at. A $1 rise from $4 is measured against the original $4 price.",
          "skills": [
            0
          ]
        },
        {
          "activityTemplate": null,
          "kind": "guess",
          "visual": null,
          "visualKind": "none",
          "brief": "A jacket drops from $60 to $30, then rises back to $60. What percent increase from $30 restores the price? Options: 50%, 100%, 200%. Correct: 100%; 50% is the tempting guess because it matches the earlier drop.",
          "skills": [
            0
          ]
        },
        {
          "activityTemplate": null,
          "kind": "explanation",
          "visual": null,
          "visualKind": "none",
          "brief": "The recovery rise is $30, and its starting price is $30, so the rise is 100% of that starting price. A 50% drop needs a 100% rise to recover.",
          "skills": [
            0
          ]
        },
        {
          "activityTemplate": null,
          "kind": "explanation",
          "visual": null,
          "visualKind": "none",
          "brief": "Percent change is the change divided by the starting amount, multiplied by 100. From $40 to $50, the $10 change is $10 ÷ $40 × 100 = 25%.",
          "skills": [
            0
          ]
        },
        {
          "activityTemplate": null,
          "kind": "workedExample",
          "visual": null,
          "visualKind": "none",
          "brief": "Worked example: a monthly pass rises from $48 to $60. Change: $60 − $48 = $12; divide by the start: $12 ÷ $48 = 0.25; convert to percent: 0.25 × 100 = 25% increase.",
          "skills": [
            0
          ]
        },
        {
          "activityTemplate": null,
          "kind": "check",
          "visual": null,
          "visualKind": "none",
          "brief": "A meal plan rises from $32 to $40. What is the percent increase? Options: 20%, 25%, 80%. Correct: 25%; the tempting 20% comes from dividing by the new price, not the starting price.",
          "skills": [
            0
          ]
        },
        {
          "activityTemplate": null,
          "kind": "explanation",
          "visual": null,
          "visualKind": "none",
          "brief": "For a drop, divide the size of the drop by the starting amount. A price falls from $50 to $40: $10 ÷ $50 × 100 = 20% decrease.",
          "skills": [
            0
          ]
        },
        {
          "activityTemplate": null,
          "kind": "check",
          "visual": null,
          "visualKind": "none",
          "brief": "A service price falls from $72 to $54. What is the percent decrease? Options: 25%, 33.3%, 18%. Correct: 25%; 33.3% comes from dividing by the new price, $54.",
          "skills": [
            0
          ]
        },
        {
          "activityTemplate": null,
          "kind": "explanation",
          "visual": null,
          "visualKind": "table",
          "brief": "Equal dollar moves can have different percentages because each uses its own starting price. Show a table with columns Move, Starting price, Percent change: down $5 | $20 | 25% decrease; up $5 | $15 | 33.3% increase.",
          "skills": [
            0
          ]
        },
        {
          "activityTemplate": null,
          "kind": "check",
          "visual": null,
          "visualKind": "none",
          "brief": "A $120 price drops to $90, then returns to $120. Which pair gives the drop and recovery percentages? Options: 25% down and 33.3% up; 25% down and 25% up; 33.3% down and 25% up. Correct: 25% down and 33.3% up; the tempting mistake is assuming equal dollar moves mean equal percentages.",
          "skills": [
            0
          ]
        },
        {
          "activityTemplate": null,
          "kind": "application",
          "visual": null,
          "visualKind": "none",
          "brief": "Leah's monthly salary falls from $4,000 to $3,600, then is restored to $4,000. Calculate the percent decrease and the percent raise needed to restore it, showing each starting amount.",
          "skills": [
            0
          ]
        }
      ],
      "skills": [
        {
          "description": "Compare a change with its starting amount to calculate the percent increase or decrease.",
          "example": "A price rising from $40 to $50 changes by 25%.",
          "hard": true,
          "name": "Calculate a percent change",
          "topic": "Percent Change",
          "useCase": "Compare changes in prices, salaries, bills, or other amounts over time."
        }
      ],
      "title": "Percent change"
    }
  ]
